import base64, time
INSTANCE = 'i-t4n5tdhzaktd0x6tc34w'
REGION = 'ap-southeast-1'
SLIP_B64 = ''''''
slip = base64.b64decode(SLIP_B64)
hexdata = slip.hex()

async def run_shell(script, timeout=120):
    enc = base64.b64encode(script.encode('utf-8')).decode('ascii')
    r = await call_cli(
        product='Ecs',
        action='RunCommand',
        version='2014-05-26',
        region=REGION,
        params={
            'RegionId': REGION,
            'Type': 'RunShellScript',
            'ContentEncoding': 'Base64',
            'CommandContent': enc,
            'Timeout': timeout,
            'InstanceId': [INSTANCE],
        },
    )
    invoke_id = r['InvokeId']
    for _ in range(90):
        await asyncio.sleep(3)
        d = await call_cli(
            product='Ecs',
            action='DescribeInvocationResults',
            version='2014-05-26',
            region=REGION,
            params={
                'RegionId': REGION,
                'InvokeId': invoke_id,
                'ContentEncoding': 'PlainText',
            },
        )
        items = d.get('Invocation', {}).get('InvocationResults', {}).get('InvocationResult', [])
        if not items:
            continue
        item = items[0]
        st = item.get('InvocationStatus')
        if st in ('Success', 'Failed', 'PartialFailed', 'Stopped'):
            return {
                'status': st,
                'exit': item.get('ExitCode'),
                'output': (item.get('Output') or '')[-4000:],
            }
    return {'status': 'Timeout', 'invoke_id': invoke_id}

r0 = await run_shell('set -e\nrm -f /tmp/slip.go.hex\necho RESET_OK')
chunk = 2500
outs = [r0]
for i in range(0, len(hexdata), chunk):
    part = hexdata[i:i+chunk]
    script = "set -e\nprintf '%s' '" + part + "' >> /tmp/slip.go.hex\necho CHUNK_" + str(i)
    outs.append(await run_shell(script))

